# owner: platform
import unittest

from hourglass.errors import OutsideHoursError
from hourglass.gaps import find_gaps
from hourglass.models import Span

OPEN = Span(540, 1020)


class FindGapsTests(unittest.TestCase):
    def test_gap_between_spans(self):
        worked = [Span(540, 720), Span(780, 1020)]
        gaps = find_gaps(worked, OPEN)
        self.assertEqual(gaps, ["gap 12:00-13:00 (60 min)"])

    def test_no_workers_is_one_gap(self):
        gaps = find_gaps([], OPEN)
        self.assertEqual(gaps, [
            "gap 09:00-17:00 (480 min)"
        ])

    def test_full_coverage_has_no_gaps(self):
        worked = [Span(540, 800), Span(800, 1020)]
        self.assertEqual(find_gaps(worked, OPEN), [])

    def test_edges_and_overlaps(self):
        worked = [Span(600, 700), Span(650, 900)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 15:00-17:00 (120 min)"
            ]
        )

    def test_unordered_input(self):
        worked = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(len(find_gaps(worked, OPEN)), 1)


class OutsideHoursTests(unittest.TestCase):
    def test_starts_too_early(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps([Span(480, 600)], OPEN)

    def test_ends_too_late(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps([Span(900, 1080)], OPEN)

    def test_error_is_a_value_error(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(0, 60)], OPEN)
